    skos:altLabel "Educational Evaluation"@en , "Test"@en , "Examination"@en ;
    rdfs:comment "The systematic process of documenting and using empirical data on knowledge, skill, attitudes, aptitude, and beliefs to refine programs and improve student learning."@en .

#################################################################
#    Axis 1: Assessment Purpose
#################################################################

ea:AssessmentPurpose
    a owl:Class ;
    rdfs:label "Assessment Purpose"@en ;
    owl:disjointUnionOf (
        ea:PlacementPurpose
        ea:FormativePurpose
        ea:SummativePurpose
        ea:DiagnosticPurpose
        ea:InterimPurpose
        ea:ScreeningPurpose
    ) .

ea:PlacementPurpose a owl:Class ; rdfs:subClassOf ea:AssessmentPurpose ; rdfs:label "Placement Purpose"@en .
ea:FormativePurpose a owl:Class ; rdfs:subClassOf ea:AssessmentPurpose ; rdfs:label "Formative Purpose"@en .
ea:SummativePurpose a owl:Class ; rdfs:subClassOf ea:AssessmentPurpose ; rdfs:label "Summative Purpose"@en .
ea:DiagnosticPurpose a owl:Class ; rdfs:subClassOf ea:AssessmentPurpose ; rdfs:label "Diagnostic Purpose"@en .
ea:InterimPurpose a owl:Class ; rdfs:subClassOf ea:AssessmentPurpose ; rdfs:label "Interim Purpose"@en .
ea:ScreeningPurpose a owl:Class ; rdfs:subClassOf ea:AssessmentPurpose ; rdfs:label "Screening Purpose"@en .

ea:PlacementAssessment
    a owl:Class ;
    rdfs:label "Placement Assessment"@en ;
    skos:altLabel "Initial Assessment"@en , "Pre-assessment"@en , "Threshold Knowledge Test"@en ;
    rdfs:subClassOf ea:EducationalAssessment ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:EducationalAssessment
            [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:PlacementPurpose ]
        )
    ] .

ea:FormativeAssessment
    a owl:Class ;
    rdfs:label "Formative Assessment"@en ;
    skos:altLabel "Assessment for Learning"@en , "Educative Assessment"@en ;
    rdfs:subClassOf ea:EducationalAssessment ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:EducationalAssessment
            [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:FormativePurpose ]
        )
    ] ;
    rdfs:comment "There is tension in the corpus regarding whether formative assessments can be graded: one viewpoint maintains that true formative assessment must be ungraded to focus purely on learning, while another notes that formative assessments may be scored or count toward course results."@en .

ea:SummativeAssessment
    a owl:Class ;
    rdfs:label "Summative Assessment"@en ;
    skos:altLabel "Assessment of Learning"@en ;
